import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

type Cell = [number, number];

// Helper: order-independent comparison of cell sets.
function sortCells(cells: Cell[]): Cell[] {
  return [...cells].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
}

describe("Game of Life - nextGeneration", () => {
  it.todo("empty grid stays empty -- [] -> []");

  it.todo(
    "single live cell dies of underpopulation (0 neighbors) -- [[0,0]] -> []",
  );

  it.todo(
    "live cell with exactly one live neighbor dies of underpopulation -- [[0,0],[1,0]] -> []",
  );

  it.todo(
    "live cell with two live neighbors survives -- middle cell of a horizontal triple stays alive",
  );

  it.todo(
    "live cell with three live neighbors survives -- cell with exactly 3 live neighbors stays alive",
  );

  it.todo(
    "live cell with four live neighbors dies of overpopulation -- center of a plus shape dies",
  );

  it.todo(
    "dead cell with exactly three live neighbors becomes alive (reproduction)",
  );

  it.todo(
    "dead cell with two live neighbors stays dead -- no reproduction with only 2",
  );

  it.todo(
    "blinker oscillates -- vertical triple [[0,-1],[0,0],[0,1]] -> horizontal triple [[-1,0],[0,0],[1,0]]",
  );

  it.todo(
    "block is a still life -- 2x2 square [[0,0],[1,0],[0,1],[1,1]] stays unchanged",
  );

  it.todo(
    "handles negative coordinates -- blinker centered at negative coords oscillates correctly",
  );
});

